/**
 * Canonical runtime sources for the two alpine conifers.
 *
 * The donor `tree10.glb`/`tree11.glb` were generated by the grass-test
 * `scripts/generate-alpine-trees.mjs` from a reference tree, and inherit three
 * things this project cannot publish as-is:
 *
 *   1. Two billboard nodes — `Tree1_Low` (holding `Empty.004`) and the baked
 *      `Tree1_Billboard`/`TreeLOD0` mesh, material and image it renders — a
 *      screen-facing impostor the runtime builds its own way. They are removed
 *      entirely.
 *   2. The needles and the settled snow are two separate vertex-coloured
 *      materials ("Evergreen needles", "Settled snow"). This project's
 *      trunk/leaf extraction reads exactly one leaf material, so the two
 *      primitives are merged into a single leaf part. Colour lives entirely in
 *      COLOR_0, which is preserved, so the merged part keeps both the green
 *      needles and the snow rind.
 *   3. tree10 is ~23k triangles against ~630 for this project's forest
 *      conifers. The merged leaf geometry is decimated with meshoptimizer to a
 *      target triangle count (see `leafTriangles` below), reported with its
 *      bounds delta.
 *
 * The trunk ("Alpine bark") is never touched, and no world-space bounds change
 * beyond what decimation unavoidably does. The result is also welded and its
 * degenerate triangles removed, so the runtime optimizer — which asserts that
 * gltfpack never changes the rendered triangle count — has nothing left to
 * drop. This script is idempotent: it always reads the unchanged donor files,
 * so a second run produces byte-identical outputs.
 *
 * The donors are Draco-compressed; decoding them needs `draco3dgltf`, the same
 * optional decoder `scripts/prepare-character-assets.mjs` relies on. It is not
 * declared in `package.json`; the script fails with a precise message if it is
 * missing (see the header of that script). The uncompressed output it writes
 * does not require it downstream.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { NodeIO } from '@gltf-transform/core';
import { ALL_EXTENSIONS } from '@gltf-transform/extensions';
import {
  dedup,
  joinPrimitives,
  prune,
  simplifyPrimitive,
  weld,
} from '@gltf-transform/functions';
import { MeshoptSimplifier } from 'meshoptimizer';
import { readGlbJson, renderedTriangleCount } from './lib/glb-inspection.mjs';
import {
  BILLBOARD_MATERIAL,
  DRACO_EXTENSION,
  assertEmbeddedTextures,
  boundsDelta,
  createSourceIo,
  dropDegenerateTriangles,
  hash,
  primitiveTriangles,
  primitiveVertices,
  replaceFileAtomically,
  sceneBounds,
  stripBillboard,
  triangleCount,
} from './lib/donor-tree-prepare.mjs';

const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const donorDirectory = process.env.ALPINE_DONOR_DIR
  ?? 'F:/Development/grass-test/public/Assets/terrain/fantasy';
// meshoptimizer's error threshold is a fraction of the mesh extent; 1 means
// "unconstrained", so the requested ratio is what actually bounds the result.
const SIMPLIFY_ERROR = 1;

/**
 * The two light conifers. `leafTriangles` is the decimation budget for the
 * merged leaf part, chosen to match the ~630-triangle forest pack plus the
 * needles-and-snow detail a winter tree needs.
 */
const ALPINE_ASSETS = Object.freeze([
  Object.freeze({
    id: 'tree10',
    donor: 'tree10.glb',
    output: 'assets/runtime-sources/trees/alpine/tree10.glb',
    species: 'Snow spruce',
    trunkMaterial: 'Alpine bark',
    leafMaterial: 'Evergreen needles',
    mergeMaterials: Object.freeze(['Evergreen needles', 'Settled snow']),
    leafTriangles: 2000,
  }),
  Object.freeze({
    id: 'tree11',
    donor: 'tree11.glb',
    output: 'assets/runtime-sources/trees/alpine/tree11.glb',
    species: 'Windswept mountain pine',
    trunkMaterial: 'Alpine bark',
    leafMaterial: 'Evergreen needles',
    mergeMaterials: Object.freeze(['Evergreen needles', 'Settled snow']),
    leafTriangles: 2000,
  }),
]);

/** 2. Merges the two vertex-coloured leaf materials into one leaf part. */
function mergeLeafParts(document, mergeMaterialNames, leafMaterialName) {
  const root = document.getRoot();
  const wanted = new Set(mergeMaterialNames);
  const leafPrimitives = [];
  const nodeOfPrimitive = new Map();
  for (const node of root.listNodes()) {
    const mesh = node.getMesh();
    if (!mesh) continue;
    for (const primitive of mesh.listPrimitives()) {
      if (wanted.has(primitive.getMaterial()?.getName())) {
        leafPrimitives.push(primitive);
        nodeOfPrimitive.set(primitive, node);
      }
    }
  }
  if (leafPrimitives.length < 2) {
    throw new Error(
      `expected one primitive per leaf material ${mergeMaterialNames.join(', ')}, `
      + `found ${leafPrimitives.length}.`,
    );
  }
  const leafMaterial = leafPrimitives[0].getMaterial();
  leafMaterial.setName(leafMaterialName);
  for (const primitive of leafPrimitives) primitive.setMaterial(leafMaterial);
  const merged = joinPrimitives(leafPrimitives);
  const keepNode = nodeOfPrimitive.get(leafPrimitives[0]);
  const leafMesh = document.createMesh('Leaves');
  leafMesh.addPrimitive(merged);
  keepNode.setMesh(leafMesh);
  for (const node of nodeOfPrimitive.values()) {
    if (node !== keepNode) node.dispose();
  }
  return { merged, leafMesh, leafMaterial, mergedFrom: leafPrimitives.length };
}

await MeshoptSimplifier.ready;

const prepared = [];

// Phase 1 — prepare every tree in memory; nothing is written until all succeed.
for (const definition of ALPINE_ASSETS) {
  const donorPath = path.join(donorDirectory, definition.donor);
  const relativeOutput = definition.output;
  let stage = 'read';
  try {
    if (!fs.existsSync(donorPath)) {
      throw new Error(`donor ${donorPath} is missing`);
    }
    const inputBytes = fs.readFileSync(donorPath);
    const donorJson = readGlbJson(inputBytes, definition.donor);
    const io = await createSourceIo(inputBytes, definition.donor);
    const document = await io.read(donorPath);
    const root = document.getRoot();
    for (const extension of root.listExtensionsUsed()) {
      if (extension.extensionName === DRACO_EXTENSION) extension.dispose();
    }
    const donorTriangles = renderedTriangleCount(donorJson);
    const donorBounds = sceneBounds(document);

    stage = 'strip billboards';
    const removedNodes = stripBillboard(document);

    stage = 'merge leaf parts';
    const merge = mergeLeafParts(document, definition.mergeMaterials, definition.leafMaterial);
    await document.transform(prune());
    const strippedBounds = sceneBounds(document);

    stage = 'decimate leaf';
    await document.transform(weld());
    const leafPrimitive = merge.leafMesh.listPrimitives()[0];
    const leafTrianglesBefore = primitiveTriangles(leafPrimitive);
    const leafVerticesBefore = primitiveVertices(leafPrimitive);
    let leafTrianglesAfter = leafTrianglesBefore;
    let leafVerticesAfter = leafVerticesBefore;
    let requestedRatio = 1;
    if (definition.leafTriangles < leafTrianglesBefore) {
      requestedRatio = definition.leafTriangles / leafTrianglesBefore;
      simplifyPrimitive(leafPrimitive, {
        simplifier: MeshoptSimplifier,
        ratio: requestedRatio,
        error: SIMPLIFY_ERROR,
        lockBorder: false,
      });
      leafTrianglesAfter = primitiveTriangles(leafPrimitive);
      leafVerticesAfter = primitiveVertices(leafPrimitive);
    }

    stage = 'clean';
    const degenerateRemoved = dropDegenerateTriangles(document);
    await document.transform(weld(), dedup(), prune());

    stage = 'validate';
    const materials = root.listMaterials().map((material) => material.getName()).sort();
    if (materials.some((name) => BILLBOARD_MATERIAL.test(name))) {
      throw new Error('a billboard material survived billboard removal.');
    }
    if (!materials.includes(definition.trunkMaterial)) {
      throw new Error(`trunk material "${definition.trunkMaterial}" was not preserved.`);
    }
    if (!materials.includes(definition.leafMaterial)) {
      throw new Error(`leaf material "${definition.leafMaterial}" was not preserved.`);
    }
    if (materials.length !== 2) {
      throw new Error(`expected exactly trunk + leaf materials, found ${materials.join(', ')}.`);
    }
    for (const node of root.listNodes()) {
      if (/(_low|_lod\d*)$/i.test(node.getName())) {
        throw new Error(`billboard/LOD node "${node.getName()}" survived.`);
      }
    }
    assertEmbeddedTextures(document, relativeOutput);

    root.getAsset().generator = 'SimCity-DnD alpine tree asset preparer';
    root.getAsset().extras = {
      preparedFrom: donorPath.replaceAll('\\', '/'),
      runtimeAsset: definition.id,
      species: definition.species,
      preparer: 'scripts/prepare-alpine-tree-assets.mjs',
      leafDecimation: {
        before: leafTrianglesBefore,
        after: leafTrianglesAfter,
        ratio: Number(requestedRatio.toFixed(6)),
      },
    };

    stage = 'write';
    const outputBytes = await new NodeIO()
      .registerExtensions(ALL_EXTENSIONS)
      .writeBinary(document);
    const outputJson = readGlbJson(Buffer.from(outputBytes), relativeOutput);
    const outputTriangles = renderedTriangleCount(outputJson);
    if (outputTriangles !== triangleCount(document)) {
      throw new Error(
        `written triangle count ${outputTriangles} does not match prepared ${triangleCount(document)}.`,
      );
    }
    const finalBounds = sceneBounds(document);

    prepared.push({
      definition,
      relativeOutput,
      outputBytes,
      donorBytes: inputBytes.length,
      donorTriangles,
      outputTriangles,
      removedNodes,
      mergedFrom: merge.mergedFrom,
      leafTrianglesBefore,
      leafTrianglesAfter,
      leafVerticesBefore,
      leafVerticesAfter,
      requestedRatio,
      degenerateRemoved,
      donorBounds,
      strippedBounds,
      finalBounds,
      decimationDelta: boundsDelta(strippedBounds, finalBounds),
      donorDelta: boundsDelta(donorBounds, finalBounds),
      inputSha256: hash(inputBytes),
      outputSha256: hash(outputBytes),
    });
  } catch (error) {
    throw new Error(`${definition.donor}: ${stage} failed: ${error.message}`);
  }
}

// Phase 2 — write every prepared tree to its canonical path.
for (const record of prepared) {
  replaceFileAtomically(record.outputBytes, path.join(rootDir, record.relativeOutput));
}

for (const record of prepared) {
  const { definition } = record;
  console.log(
    `${definition.id} (${definition.species}): `
    + `${record.donorTriangles} -> ${record.outputTriangles} triangles | `
    + `leaf ${record.leafTrianglesBefore} -> ${record.leafTrianglesAfter} `
    + `(${record.leafVerticesBefore} -> ${record.leafVerticesAfter} vertices, `
    + `ratio ${record.requestedRatio.toFixed(3)}) | `
    + `stripped [${record.removedNodes.map((n) => `"${n}"`).join(', ')}] | `
    + `merged ${record.mergedFrom} leaf primitives -> 1 ("${definition.leafMaterial}") | `
    + `${record.degenerateRemoved} degenerate triangles removed | `
    + `${(record.donorBytes / 1024).toFixed(1)} -> `
    + `${(record.outputBytes.length / 1024).toFixed(1)} KiB`,
  );
}

const columns = [
  ['asset', 8],
  ['tris in', 9],
  ['tris out', 9],
  ['leaf out', 9],
  ['billboard', 24],
  ['bounds delta', 12],
  ['KiB in', 9],
  ['KiB out', 9],
];
console.log('');
console.log(columns.map(([title, width]) => title.padEnd(width)).join('  '));
console.log(columns.map(([, width]) => '-'.repeat(width)).join('  '));
for (const record of prepared) {
  console.log([
    record.definition.id.padEnd(8),
    String(record.donorTriangles).padEnd(9),
    String(record.outputTriangles).padEnd(9),
    String(record.leafTrianglesAfter).padEnd(9),
    record.removedNodes.join(',').padEnd(24),
    record.decimationDelta.toFixed(4).padEnd(12),
    (record.donorBytes / 1024).toFixed(1).padEnd(9),
    (record.outputBytes.length / 1024).toFixed(1).padEnd(9),
  ].join('  '));
}
console.log('');
console.log('world-space bounds (donor -> final; delta from billboard removal + decimation):');
for (const record of prepared) {
  console.log(
    `  ${record.definition.id}: [${record.donorBounds.min.join(', ')}] .. `
    + `[${record.donorBounds.max.join(', ')}] -> `
    + `[${record.finalBounds.min.join(', ')}] .. [${record.finalBounds.max.join(', ')}] `
    + `(decimation-only delta ${record.decimationDelta.toFixed(6)}, total delta ${record.donorDelta.toFixed(6)})`,
  );
}
console.log(`prepared ${prepared.length} alpine tree sources`);
